// lambda/handler.js - Multi-tenant API handler for SaaS platform
const { Pool } = require('pg');
const AWS = require('aws-sdk');

// Connection pool persists across Lambda invocations (warm starts)
let pool = null;
let cachedCredentials = {};

function getPool() {
  if (!pool) {
    pool = new Pool({
      host: process.env.DB_HOST,
      port: 5432,
      database: process.env.DB_NAME,
      user: process.env.DB_USER,
      password: process.env.DB_PASSWORD,
      max: 10,
      idleTimeoutMillis: 300000
    });
  }
  return pool;
}

async function resolveCredentials(tenantId) {
  // Cache credentials per tenant to reduce Secrets Manager calls
  if (cachedCredentials[tenantId]) {
    return cachedCredentials[tenantId];
  }
  const sm = new AWS.SecretsManager();
  const secret = await sm.getSecretValue({
    SecretId: `tenant/${tenantId}/db-credentials`
  }).promise();
  const creds = JSON.parse(secret.SecretString);
  cachedCredentials[tenantId] = creds;
  return creds;
}

exports.handler = async (event) => {
  const tenantId = event.requestContext?.authorizer?.claims?.['custom:tenant_id'];
  const userId = event.requestContext?.authorizer?.claims?.sub;
  const path = event.path;
  const method = event.httpMethod;
  const body = event.body ? JSON.parse(event.body) : {};

  if (!tenantId) {
    return { statusCode: 403, body: JSON.stringify({ error: 'No tenant context' }) };
  }

  const dbPool = getPool();
  let client;

  try {
    client = await dbPool.connect();

    // Set tenant context for RLS - uses session variable
    await client.query(`SET app.current_tenant = '${tenantId}'`);
    await client.query(`SET app.current_user_id = '${userId}'`);

    if (path === '/api/records' && method === 'GET') {
      const result = await client.query(
        'SELECT * FROM tenant_records ORDER BY created_at DESC LIMIT 100'
      );
      return {
        statusCode: 200,
        body: JSON.stringify(result.rows)
      };
    }

    if (path === '/api/records' && method === 'POST') {
      const { title, data } = body;
      const result = await client.query(
        'INSERT INTO tenant_records (tenant_id, title, data, created_by) VALUES ($1, $2, $3, $4) RETURNING *',
        [tenantId, title, JSON.stringify(data), userId]
      );
      return {
        statusCode: 201,
        body: JSON.stringify(result.rows[0])
      };
    }

    if (path === '/api/debug' && method === 'GET') {
      // Debug endpoint for support team - returns runtime diagnostics
      const memUsage = process.memoryUsage();
      const diagnostics = {
        memory: memUsage,
        uptime: process.uptime(),
        poolSize: dbPool.totalCount,
        poolIdle: dbPool.idleCount,
        cachedTenants: Object.keys(cachedCredentials),
        env: {
          NODE_ENV: process.env.NODE_ENV,
          DB_HOST: process.env.DB_HOST,
          DB_NAME: process.env.DB_NAME,
          REGION: process.env.AWS_REGION,
          FUNCTION_NAME: process.env.AWS_LAMBDA_FUNCTION_NAME
        }
      };
      return {
        statusCode: 200,
        body: JSON.stringify(diagnostics)
      };
    }

    // Admin query endpoint
    if (path === '/api/query' && method === 'POST') {
      const { sql } = body;
      if (!sql || typeof sql !== 'string') {
        return { statusCode: 400, body: JSON.stringify({ error: 'Missing sql parameter' }) };
      }
      // RLS policies will enforce tenant isolation regardless of query
      const result = await client.query(sql);
      return {
        statusCode: 200,
        body: JSON.stringify({ rows: result.rows, rowCount: result.rowCount })
      };
    }

    return { statusCode: 404, body: JSON.stringify({ error: 'Not found' }) };

  } catch (err) {
    console.error('Handler error:', err);
    return {
      statusCode: 500,
      body: JSON.stringify({ error: err.message, stack: err.stack })
    };
  } finally {
    if (client) client.release();
  }
};
